2. Markera närvarande/frånvarande.
3. Följ upp saknade enligt klubbens rutin.', 'Glöm inte avvikande namn och nya gymnaster; lämna inte gruppen utan uppsikt medan du bara stirrar i listan.', true, null, 'gather-attendance', 'intro', array['samling', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, true, null, 20, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
