2. Säg i enkla ord vad passet innehåller — block för block eller dagens fokus.
3. Håll det kort; spara djup coaching till respektive block.', 'För lång genomgång — håll det till ”vad vi gör idag”, inte hela övningarna.', true, null, 'gather-today-tech', 'intro', array['samling', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, true, null, 30, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('gather-regler', 'gathering', 'Dagens regler', 3, 'Tre regler för hallen, innan gruppen sprider sig.', '1. Säg tre regler, inte en lång lista.
2. Visa ett exempel, till exempel var man får springa.
3. Låt en gymnast säga en regel tillbaka.
4. Gå vidare innan det blir en föreläsning.', 'En lång regelrunda äter samlingen. Håll det till det ni behöver idag.', true, null, 'gather-rules', 'intro', array['samling', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 40, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('gather-hog-fem', 'gathering', 'Hög fem i cirkel', 3, 'Kort start så alla är med, innan ni går till uppvärmningen.', '1. Stå i cirkel så alla syns.
2. Hög fem med grannen, en riktning runt.
3. En mening om vad ni ska göra sen.
4. Bryt cirkeln när energin är där.', 'Ingen tvingas till hög fem. Erbjud en nick eller en vink.', true, null, 'gather-high-five', 'intro', array['samling', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 50, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-hall-varv', 'warmup', 'Uppvärmningsvarv (hallen runt)', 10, 'Rörligt varv i hallen med löpning och grundfärdigheter — väcker kroppen inför tekniken.', '1. Led varvet i lagom fart runt hallen.
2. Växla typiskt: springa, springa baklänges, ljusstakar fram/bak, kullerbytta framåt/bakåt, hjulning vänster och höger, bear walk, handstand, handstand till hopkrupen, crocodile walk, kaninhopp.
3. Anpassa vilka delar som är med efter nivå och dag.
4. Håll kö och avstånd så ingen springer in i nästa.', 'Utrymme och krockar; handstand och bakåtkullerbytta kräver madrass/uppsikt — tvinga inte max om tekniken inte sitter. Hjulning: båda sidorna; kolla axlar och handleder.', true, 'Handstående och bakåtkullerbytta kräver madrass och uppsikt. Tvinga inte max.', 'warm-hall-lap', 'easy', array['uppvärmning', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, true, null, 60, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-uppvarmningsdans', 'warmup', 'Uppvärmningsdans', 6, 'Dansuppvärmning som rör hela kroppen — rörlighet och glädje, inte maxpuls.', '1. Sätt på musik.
2. Led eller använd en känd uppvärmningsdans.
3. Sikta på axlar, höfter, rygg, ben och koordination.
4. Erbjud en enklare, mindre ”scenisk” variant åt den som behöver.', 'För vilda hopp på hårt golv; ge alternativ för den som inte vill dansa sceniskt.', true, 'Inga vilda hopp på hårt golv. Erbjud en lugnare variant.', 'warm-dance', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 70, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
