2. Andas lugnt; håll ca 15–30 s per sida där det passar.
3. Håll samma ordning så gruppen känner igen flödet.', 'Studsande stretch; smärta ≠ ”bra”; anpassa för hypermobila gymnaster.', true, 'Studsa inte i stretchen. Smärta är inte målet.', 'warm-stretch-coach', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 100, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
