2. Gå en led över golvet, ett djur i taget.
3. Byt djur efter varje vända.
4. Håll kön så ingen startar förrän ytan är fri.', 'Handleder och avstånd. Ingen kapplöpning in i nästa.', true, 'Håll avstånd mellan leden. Inga hopp på hårt golv.', 'warm-animals', 'easy', array['uppvärmning', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 110, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-fotarbete', 'warmup', 'Fotarbete på stället', 4, 'Lätt fötter på egen ruta — jogg, galopp och små hopp, inte en tävling.', '1. Varje gymnast har en egen ruta, inte en tät klunga.
2. Lätt jogg, galopp och små jämfotahopp på stället.
3. Mjuka landningar. Armarna hjälper balansen.
4. Avsluta med att stå stilla och andas.', 'Hårda landningar och hopp som blir tävling.', true, 'Mjuka landningar. Ingen maxhopp på hårt golv.', 'warm-feet', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 120, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
