2. En i taget; tydlig kö.
3. Cue: timing och rak kropp före höjd.', 'Fel fotisättning på brädan; landning bakom/framför mattan; köhållning så ingen springer in för tidigt.', true, 'En i taget. Ingen springer in förrän landningen är klar.', 'tech-ljushopp-board', 'easy', array['teknik', 'vault', 'new-coach-ok']::text[], '[{"pieceId":"eq-satsbrada","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, false, null, 130, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
