2. Spotting och madrassuppställning före första försöket.
3. En i taget; stoppa tidigt vid osäkra försök.', 'Under-/överrotation; landningszon; trötthet i kön. Stoppa tidigt vid osäkra försök.', true, 'Endast med erfaren ledare, spotting och madrass före första försöket. Stoppa osäkra försök.', 'tech-salto-height', 'hard', array['teknik', 'floor', 'experienced-coach-only']::text[], '[{"pieceId":"eq-plint","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, true, false, false, null, 200, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-handstaende-falla-rygg', 'techniques', 'Handstående falla till rygg', 6, 'Från handstående, kontrollerad fall till rygg — öppning och trygg bakåtlandning.', '1. Lägg madrass bakom innan någon går upp i handstående.
2. Handstående (mot vägg eller fri enligt nivå) → tippa/falla till rygg.
3. Cue öppning och mjuk landning på rygg.', 'Huvud/nacke; axlar som kollapsar; madrass bakom måste finnas innan de går upp.', true, 'Madrass bakom innan någon går upp i handstående.', 'tech-hs-fall-back', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 210, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-kullerbytta', 'techniques', 'Kullerbytta framåt', 6, 'En trygg kullerbytta framåt på matta — rund rygg, inte ett kast.', '1. Lägg madrassen fram. Visa haka i och rund rygg.
2. En i taget från huk, händerna i mattan.
3. Rulla upp till fötterna utan att sätta fart i väggen.
4. Nästa startar först när mattan är fri.', 'Platt rygg, hakan upp, eller någon som skjuter på bakifrån.', true, 'Madrass under. Hakan i. Nästa väntar tills mattan är fri.', 'tech-roll', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 220, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-hjul', 'techniques', 'Hjul', 6, 'Hjul åt båda håll på en fri linje — händer och fötter i en bana.', '1. Markera en linje på golvet.
2. Visa hjul med magen in och blicken på händerna.
3. En i taget, först ett håll och sedan det andra.
4. Ingen står i landningen.', 'Böjd bana, någon i vägen, eller bara ett håll.', true, 'Fri bana. En i taget. Båda hållen, utan att någon står i vägen.', 'tech-cartwheel', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 230, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-bro', 'techniques', 'Bro', 5, 'Bro med egna händer och fötter. Ingen trycker ner ryggen.', '1. Madrass. Ligg på rygg, fötterna nära rumpan, händerna vid öronen.
2. Lyft höfterna till bro, eller stanna på en lägre båge.
3. Håll en kort stund och kom ner på ryggen, inte på huvudet.
4. En i taget om ytan är liten.', 'Någon som trycker på magen eller ryggen. Handleder som viker sig.', true, 'Ingen trycker ner ryggen. Avbryt om handlederna gör ont.', 'tech-bridge', 'easy', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, false, null, 240, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-balansgang', 'techniques', 'Balansgång', 5, 'Balans på en linje på golvet. Armarna ut, inte en upphöjd bänk.', '1. Markera en linje, eller ställ koner som gång.
2. Gå framåt med blicken långt fram.
3. Armarna ut. Vänd kontrollerat.
4. En i taget om linjen är smal.', 'De tittar i golvet och tappar linjen. Ingen kliver upp på plint eller bänk.', true, 'Linjen är på golvet, inte på en upphöjd bänk. En i taget.', 'tech-balance', 'intro', array['teknik', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-kon","count":4}]'::jsonb, null, null, null, false, true, false, null, 250, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-grenhopp-trampett', 'techniques', 'Grenhopp från trampett', 6, 'Grenform i luften och en stabil landning. Första steget mot att hoppa former från trampett med kontroll, inte höjd.', '1. Kort ansats, studs mitt i trampetten.
2. Benen ut åt sidorna och fram, armarna sträcks mot tårna.
3. Samla benen före landning och landa på två fötter på mattan: böjda knän, armarna fram.
4. En i taget, nästa går när mattan är fri.', 'Lång eller snabb ansats, studs nära kanten, benen kvar isär i landningen.', true, 'Landningsmatta direkt efter trampetten. En i taget. Ingen springer in förrän landningen är klar.', 'tech-straddle-trampett', 'easy', array['teknik', 'trampett', 'hopp', 'landning', 'grenhopp', 'new-coach-ok']::text[], '[{"pieceId":"eq-trampett","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, 'tech-landning-plint', 'tech-formhopp-over-block', false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=16","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":16}'::jsonb, 260, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-formhopp-over-block', 'techniques', 'Formhopp över block från trampett', 6, 'Ett lågt block mellan trampett och matta ger gymnasten ett mål att hoppa över. Tränar höjd, form i luften och landning.', '1. Ställ ett lågt mjukt block mellan trampetten och landningsmattan.
2. Studsa och hoppa över blocket med en form: ljushopp, krupen eller gren.
3. Landa på två fötter på mattan med böjda knän.
4. Bygg på med fler block när landningarna sitter.', 'Fötter som tar i blocket, gymnaster som tittar ner, att svårigheten höjs innan landningen är stabil.', true, 'Bara mjuka block, aldrig hårda kanter. Landningsmattan ska räcka långt bakom blocket. En i taget.', 'tech-shape-over-block', 'easy', array['teknik', 'trampett', 'hopp', 'former', 'landning', 'new-coach-ok']::text[], '[{"pieceId":"eq-trampett","count":1},{"pieceId":"eq-skumblock","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, 'tech-grenhopp-trampett', null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=30","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":30}'::jsonb, 270, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-aggrullning-kil', 'techniques', 'Äggrullning nerför kil', 6, 'Gymnasten håller en hopkrupen form medan kroppen rullar nerför kilen. Bygger spänning, rund form och trygghet i att rotera.', '1. Lägg kilen på en matta. Gymnasten ligger på rygg högst upp.
2. Dra upp knäna, håll om dem och för hakan mot bröstet.
3. Rulla nerför kilen och håll formen hela vägen ner.
4. Nästa startar när ytan nedanför är fri.', 'Formen som släpper (ben eller armar åker ut), hakan som åker upp.', true, 'Kilen ligger stadigt på en matta. Bara en i taget i backen.', 'tech-egg-roll-wedge', 'intro', array['teknik', 'rullning', 'kil', 'form', 'nybörjare', 'new-coach-ok']::text[], '[{"pieceId":"eq-kilmatta","count":1},{"pieceId":"eq-madrass","count":1}]'::jsonb, null, null, null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=50","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":50}'::jsonb, 280, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-l-hang-racke', 'techniques', 'L-häng i räcke', 6, 'Gymnasten hänger med raka armar och lyfter benen framåt. Tränar bål och grepp som behövs i räckesövningar.', '1. Gymnasten hänger i räcket med raka armar.
2. Lyft benen fram så raka som möjligt, tårna pekar framåt.
3. Håll några sekunder och sänk benen lugnt.
4. Böj knäna om raka ben inte går än.', 'Gungande kropp, böjda armar, ben som faller ner okontrollerat.', true, 'Matta under räcket. Räcket så lågt att gymnasten når själv. Ledare nära vid första försöken.', 'tech-l-hang-bar', 'easy', array['teknik', 'räcke', 'bål', 'grepp', 'styrka', 'new-coach-ok']::text[], '[{"pieceId":"eq-racke","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=99","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":99}'::jsonb, 290, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-stod-racke-pendel', 'techniques', 'Stöd på räcke med pendel', 6, 'Upp i stöd på räcket med raka armar och spänd kropp. Grunden för alla räckesövningar och en trygg nedgång.', '1. Gymnasten trycker sig upp i stöd, raka armar, händerna ovanpå stången.
2. Håll kroppen rak och spänd. Pendla benen fram och bak tre gånger.
3. Tryck ifrån bakåt och landa på mattan: böjda knän, armarna fram.', 'Böjda armar, axlar som sjunker, höfter som viker sig vid stången, landning för nära räcket.', true, 'Matta under och bakom räcket. Räcket i lagom höjd för gruppen. Ledare står nära vid nedgången.', 'tech-support-bar', 'easy', array['teknik', 'räcke', 'stöd', 'landning', 'new-coach-ok']::text[], '[{"pieceId":"eq-racke","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=115","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":115}'::jsonb, 300, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-asnesparkar', 'techniques', 'Åsnesparkar', 6, 'Ett litet hopp upp på händerna med benen sparkade bakåt. Tidigt steg mot att våga lägga vikten på händerna inför handstående.', '1. Armarna raka och upp framför kroppen, ett ben böjt fram och ett rakt bak.
2. Sätt händerna i mattan, skjut ifrån med det främre benet och sparka upp bakåt.
3. Landa mjukt på fötterna. Byt ben varannan gång.', 'Armar som viker sig, huvudet långt fram mellan armarna, bara ett ben.', true, 'Matta under. Avstånd mellan gymnasterna så ingen får en spark. Ingen tävling om höjd.', 'tech-donkey-kick', 'easy', array['teknik', 'handstående', 'golv', 'armstöd', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-tumblingmatta","count":1}]'::jsonb, null, null, null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=146","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":146}'::jsonb, 310, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-minihjul', 'techniques', 'Minihjul (krabbhjul)', 6, 'Ett litet hjul nära golvet: hand, hand, fot, fot. Lär rytmen och handisättningen i hjulet utan höjd.', '1. Börja på huk vid ena sidan av mattan, armbågarna nära kroppen.
2. Sätt ner händerna en i taget och hoppa över fötterna till andra sidan: hand, hand, fot, fot.
3. Gör åt båda håll.
4. Höj höfterna lite mer när rytmen sitter.', 'Fel ordning på händer och fötter, händer som hamnar för långt bort, bara ett håll.', true, 'Fri bana. En i taget på mattan. Ingen står där fötterna landar.', 'tech-mini-cartwheel', 'intro', array['teknik', 'hjul', 'golv', 'nybörjare', 'floor', 'new-coach-ok']::text[], '[{"pieceId":"eq-tumblingmatta","count":1}]'::jsonb, null, null, 'tech-hjul', false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=165","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":165}'::jsonb, 320, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-soldatsparkar-bom', 'techniques', 'Soldatsparkar på bom', 6, 'Gå längs bommen och sparka fram med raka ben. Tränar balans, raka ben och spänd kropp på smal yta.', '1. Armarna ut åt sidan för balansen.
2. Ta ett steg och sparka det andra benet rakt fram, tårna pekar.
3. Byt ben varje steg hela vägen till slutet.
4. Hoppa ner i slutet och landa på två fötter med böjda knän.', 'Böjda ben, blicken ner i bommen, för snabbt tempo.', true, 'Låg bom med matta bredvid och vid nedhoppet. En i taget på bommen.', 'tech-soldier-kicks-beam', 'easy', array['teknik', 'bom', 'balans', 'raka ben', 'new-coach-ok']::text[], '[{"pieceId":"eq-bom","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, 'tech-balansgang', null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=184","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":184}'::jsonb, 330, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-krabbgang-bom', 'techniques', 'Krabbgång längs bom', 6, 'Bakåtstöd med händerna på bommen och förflyttning i sidled. Bygger stark axelposition och raka armar.', '1. Sitt bredvid bommen och sätt händerna på den bakom dig.
2. Lyft till bakåtstöd med raka armar och så raka ben som möjligt.
3. Flytta händer och fötter i sidled längs hela bommen.', 'Böjda armar, höfter som sjunker mot golvet, axlar som åker upp mot öronen.', true, 'Bom som står stadigt på golvet. Avbryt om handlederna eller axlarna gör ont.', 'tech-crab-walk-beam', 'easy', array['teknik', 'bom', 'stöd', 'axlar', 'styrka', 'new-coach-ok']::text[], '[{"pieceId":"eq-bom","count":1}]'::jsonb, null, null, null, false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=205","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":205}'::jsonb, 340, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
