2. Hoppa ner med en form, t.ex. ljushopp eller krupen.
3. Landa stilla på golvet i samma landning och håll två sekunder.', 'Raka ben i landningen, knän som faller inåt, att gymnasten tar steg efter landningen.', true, 'Låg och stadig plint. Mjukt underlag vid nedhoppet. En i taget.', 'tech-stick-landing-box', 'intro', array['teknik', 'landning', 'hopp', 'plint', 'nybörjare', 'new-coach-ok']::text[], '[{"pieceId":"eq-plint","count":1}]'::jsonb, null, null, 'tech-grenhopp-trampett', false, true, true, '{"url":"https://youtu.be/2DJ_oMM81mI?t=245","creator":"Prime Coaching Sport","title":"Fun gymnastics stations","startSeconds":245}'::jsonb, 360, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('strength-cirkeltraning', 'strength', 'Cirkelträning (par, stationer)', 12, 'Cirkel med flera stationer; gymnaster går runt i par — teknik före tempo.', '1. Sätt 4–8 stationer med lagom avstånd.
2. Visa varje station kort innan start.
3. 30 s arbete, 20 s vila/byte; jobba i par.
4. Håll tiden tydligt (timer eller musiksignal).', 'Stationer för tätt; teknik före tempo; anpassa så nybörjare inte tar skadliga genvägar.', true, 'Teknik före tempo. Låt inte nybörjare ta skadliga genvägar.', 'str-circuit', 'easy', array['styrka', 'group', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 370, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('strength-burpee-emom', 'strength', 'Burpee-challenge (EMOM)', 8, 'Burpees EMOM (every minute on the minute) — tydlig nivå och tillåtna regressioner.', '1. Visa korrekt burpee först.
2. Varje minut: bestämt antal (eller max under resten av minuten enligt vald variant).
3. Vila till nästa minutstart; sätt nivå efter gruppen.
4. Tillåt step-back / utan hopp när formen faller.', 'Ojämn form när de blir trötta (höfter sjunker, hopp blir slarviga); erbjud regression tidigt.', true, 'Avbryt setet när formen faller. Step-back eller utan hopp är tillåtet.', 'str-burpee', 'easy', array['styrka', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 380, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('strength-styrkelatar', 'strength', 'Styrkelåtar (Sally, Thunderstruck, Gimme Gimme, jägarvila)', 5, 'Styrka till kända låtar — t.ex. Sally, Thunderstruck, Gimme Gimme Gimme eller jägarvila hela låten.', '1. Välj en låt (en eller två räcker ofta i ett pass).
2. Förklara rörelsen innan musiken startar.
3. Synka till refränger/verser enligt klubbrutin (Sally = upp/ner till texten; Thunderstruck = burpee/jump-variation; Gimme = vald styrkeövning; jägarvila = holds hela låten).', 'Knän/hållning i squat; axlar i holds; erbjud knästående/kortare hold. Volym — en eller två låtar räcker ofta.', true, 'Knän och axlar håller formen. En eller två låtar räcker.', 'str-songs', 'intro', array['styrka', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 390, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('strength-planka', 'strength', 'Planka i lag', 6, 'Kort planka där formen vinner över tiden.', '1. Visa planka på tå och på knä.
2. 15–20 sekunder, vila, en omgång till.
3. Knäversionen är den vanliga, inte ett straff.
4. Avbryt när höften tappar eller ryggen svankar.', 'Svank, och tävling om vem som håller längst.', true, 'Höfterna får sjunka till knäna. Avbryt om ryggen gör ont.', 'str-plank', 'easy', array['styrka', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 400, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('strength-djurkryp', 'strength', 'Björngång och krabba', 6, 'Björngång och krabbkryp som styrka, inte som race.', '1. Visa björn och krabba på en kort bana.
2. Gå över, vila, byt djur.
3. Håll handlederna så att det inte gör ont.
4. Ingen startar mot en kompis i samma bana.', 'Tävling och handleder som viker sig.', true, 'Korta banor. Ingen tävling in i varandra.', 'str-crawl', 'easy', array['styrka', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 410, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-rundpingis-medicinboll', 'fun_and_games', 'Rundpingis med medicinboll', 6, 'Pingis-/rundspel med medicinboll i stället för vanlig boll — lagom vikt för åldern.', '1. Ställ upp cirkel eller er vanliga rundpingis-uppställning.
2. Välj medicinboll med lagom vikt för åldern.
3. Sätt tydliga gränser för hur hårt de får kasta.', 'Ansikte/händer — för tung boll eller hårda kast; anpassa bollvikt.', true, 'Lagom bollvikt. Inga hårda kast mot ansikte eller händer.', 'fun-medball', 'intro', array['lek', 'group', 'new-coach-ok']::text[], null, array['medicinboll']::text[], null, null, false, true, false, null, 420, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-hojdhopp', 'fun_and_games', 'Höjdhopp (lek)', 6, 'Lekfullt höjdhopp över ribba eller mjuk höjd — höj stegvis med trygg landning.', '1. Sätt en säker ”ribba” (elastiskt band, moppskaft på koner eller mjuka mattor).
2. En i taget eller stafettvariant.
3. Höj stegvis; landning i mjuk zon.', 'Landning på två fötter i mjuk zon; ingen hård ribba i ansiktshöjd; köordning.', true, 'Mjuk landning på två fötter. Ingen hård ribba i ansiktshöjd.', 'fun-highjump', 'intro', array['lek', 'group', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 430, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-stafett', 'fun_and_games', 'Stafett', 8, 'Klassisk stafett — lag, sträcka och växling med fair start.', '1. Dela lag.
2. Bestäm bana och vad som bärs/görs vid växling.
3. Demonstrera en gång; fair start.', 'Hala golv i kurvor; krockar i växling; håll banan fri från redskap.', true, 'Håll banan fri från redskap. Se upp för krockar i växlingen.', 'fun-relay', 'intro', array['lek', 'group', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 440, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-123-forflyttning', 'fun_and_games', '1-2-3 (förflyttningslek)', 4, 'Förflyttningslek: 1 = den framför går bak, 2 = den bak går fram, 3 = spring — skilt från voltpositionernas 1-2-3.', '1. Ställ gymnasterna i led/par enligt er uppställning.
2. Ropa 1, 2 eller 3.
3. 1: personen längst fram flyttar sig längst bak. 2: personen längst bak flyttar sig längst fram. 3: alla springer (t.ex. till linje och tillbaka).', 'Krockar vid 3; tydliga gränser i hallen.', true, 'Tydliga gränser i hallen så ingen krockar när ni springer.', 'fun-123-move', 'intro', array['lek', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 450, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-maffia', 'fun_and_games', 'Maffia', 10, 'Maffia-lek (social/rollek) enligt klubbens variant — håll det kort och åldersanpassat.', '1. Använd er vanliga Maffia-uppsättning (roller, ”natt/dag”, ledare som berättar).
2. Håll det åldersanpassat; byt roller ofta.
3. Ingen fysisk ”attack”.', 'Uteslutning/önskan — byt roller ofta; ingen fysisk attack.', true, 'Ingen fysisk attack. Byt roller ofta.', 'fun-mafia', 'intro', array['lek', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, true, null, 460, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-handstaende-utmaning', 'fun_and_games', 'Handstående-utmaning', 5, 'Lekfull utmaning — håll handstående eller flest kontrollerade försök med bra form.', '1. Mot vägg eller med kompisstöd efter nivå; madrass redo.
2. Mät tid eller antal kontrollerade försök.
3. Belöna form, inte bara ”vågat”; tillåt knä/björn-alternativ.', 'Fall utan madrass; nacke; tävlingshets som ger slarviga uppsättningar.', true, 'Madrass redo. Belöna form, inte bara att någon vågar.', 'fun-hs-challenge', 'easy', array['lek', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 470, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-huvudstaende-utmaning', 'fun_and_games', 'Stå-på-huvud-utmaning', 5, 'Huvudstående-utmaning med fokus på trygg upp- och nedgång.', '1. Triangelbas, madrass, gärna mot vägg först.
2. Utmana tid med bra form.
3. Spotting för dem som är nya.', 'Belastning på nacke/huvud — avbryt vid smärta; aldrig utan madrass; ingen som ”knuffar upp” andra.', true, 'Aldrig utan madrass. Avbryt vid smärta. Ingen knuffar upp någon annan.', 'fun-headstand', 'easy', array['lek', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 480, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('fun-morkerkurragomma', 'fun_and_games', 'Mörkerkurragömma', 10, 'Kurragömma med dämpad belysning i hallen — tydliga regler innan ljuset skruvas ner.', '1. Sätt regler innan mörker: var man får gömma sig, var man inte får (förråd, redskapsskåp, ovanpå plintar som kan tippa), hur man blir tagen, när ljuset tänds.
2. Behåll nöd-/utgångsljus enligt hallens krav.
3. Räkna in alla efteråt innan ni lämnar.', 'Fall i mörker; gömställen under tunga redskap; rädsla — erbjud ”ljusvakt”-roll. Räkna in hela gruppen.', true, 'Regler innan ljuset dämpas. Nödutgångsljus på. Räkna in alla efteråt.', 'fun-dark-hide', 'easy', array['lek', 'group', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 490, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
